// ① 목록에 있나
KARMOLAB_LAZY_META_BY_ID['그도구id']

// ② 파일이 왔나 (Network 탭에서 그 이름 검색, 또는)
performance.getEntriesByType('resource').filter((r) => r.name.includes('그도구id'))

// ③ 등록까지 됐나
Toolbox.getTools().find((t) => t.id === '그도구id')

// 리스너가 몇 번 도나 (중복 판정)
// 핸들러 첫 줄에 넣는다
console.count('[DEBUG-a4f2] click');

// 요소를 찾긴 했나 (null 판정)
console.log('[DEBUG-a4f2]', container.querySelector('.target'));

// 이벤트가 오긴 하나 (위임 확인)
container.addEventListener('click', (e) => console.log('[DEBUG-a4f2]', e.target), true);

[...document.querySelectorAll('*')]
  .filter((el) => el.getBoundingClientRect().right > document.documentElement.clientWidth + 1)
  .forEach((el) => console.log(Math.round(el.getBoundingClientRect().right), el));

// 선택한 요소의 최종 값 보기
getComputedStyle($0).display
getComputedStyle($0).minWidth

// 이 도구가 무엇을 저장해 두었나
Object.keys(localStorage).filter((k) => k.startsWith('kl:그도구id'))

// 저장된 값이 범인인지 보기 (지우기 전에 복사해 두라)
const backup = { ...localStorage };

// 캐시가 범인인가 — 강제 새로고침으로 갈린다
// (또는 Application → Service Workers → Unregister)

console.time('draw'); render(); console.timeEnd('draw');

// 몇 번 불렸나 (과도한 렌더 잡기)
console.count('render');

// 무거운 구간 표시 — Performance 기록에 이름으로 뜬다
performance.mark('a'); heavy(); performance.mark('b');
performance.measure('heavy', 'a', 'b');

// 요소가 몇 개나 있나 (너무 많이 만들고 있나)
document.querySelectorAll('*').length
